create or replace function private.staff_directory() returns jsonb language plpgsql stable security definer set search_path='' as $$ begin if not private.has_role('Administrator') then raise exception 'Administrator access required'; end if; return (select coalesce(jsonb_agg(jsonb_build_object('email',s.email,'name',coalesce(nullif(s.name,''),u.raw_user_meta_data->>'name',''),'role',s.role,'roles',s.roles,'last_login',u.last_sign_in_at) order by s.email),'[]'::jsonb) from private.staff_emails s left join auth.users u on lower(u.email)=s.email); end $$;
